def executeJavaScript(sandbox_id, code, stdin=None, timeout_seconds=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        suffix = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{suffix}"

    def _record_usage(usage, api_key_id, tool, status, error_code=None, sandbox_id_val=None, execution_id_val=None, file_id=None, request_bytes=None, response_bytes=None):
        now = _now()
        ue = {
            "id": _gen_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id_val,
            "execution_id": execution_id_val,
            "file_id": file_id,
            "tool": tool,
            "status": status,
            "request_bytes": request_bytes,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        usage.append(ue)
        return ue

    def _within_today(dt_str, now_utc):
        dt = _parse_dt(dt_str)
        if not dt:
            return False
        start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start <= dt < end

    def _count_today(usage, api_key_id, tools, statuses, now_utc):
        c = 0
        for e in usage:
            if e.get("api_key_id") != api_key_id:
                continue
            if e.get("tool") not in tools:
                continue
            if e.get("status") not in statuses:
                continue
            if _within_today(e.get("occurred_at"), now_utc):
                c += 1
        return c

    def _rate_limited(usage, api_key_id, rps, now_utc):
        try:
            rps = float(rps)
        except Exception:
            return False
        if rps <= 0:
            return False
        window_start = now_utc - datetime.timedelta(seconds=1)
        cnt = 0
        for e in usage:
            if e.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(e.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start and dt <= now_utc:
                cnt += 1
        return cnt >= rps

    def _maybe_expire_sandbox(sb, now_utc):
        if not isinstance(sb, dict):
            return False
        if sb.get("status") in ("expired",):
            return False
        ttl = sb.get("idle_ttl_seconds")
        last = _parse_dt(sb.get("last_activity_at")) if sb.get("last_activity_at") else None
        if not isinstance(ttl, int) or ttl < 30 or ttl > 86400:
            return False
        if not last:
            return False
        # Apply on any non-terminal status except provisioning (no activity yet)
        if sb.get("status") in ("ready", "busy", "stopped", "error"):
            if now_utc - last > datetime.timedelta(seconds=ttl):
                if sb.get("status") != "expired":
                    sb["status"] = "expired"
                    sb["updated_at"] = _iso(now_utc)
                    return True
        return False

    t0 = time.time()
    now = _now()

    # Validate inputs
    if not isinstance(sandbox_id, str) or not re.match(r"^se2b_sbx_[0-9A-Z]{18,}$", sandbox_id):
        return _err("VALIDATION_ERROR", "sandbox_id is invalid.", field="sandbox_id")
    if not isinstance(code, str) or code.strip() == "":
        return _err("VALIDATION_ERROR", "code is required and must be non-empty.", field="code")
    if stdin is not None and not isinstance(stdin, str):
        return _err("VALIDATION_ERROR", "stdin must be a string.", field="stdin")
    if timeout_seconds is None:
        timeout_seconds = 60
    if not isinstance(timeout_seconds, int) or timeout_seconds < 1 or timeout_seconds > 600:
        return _err("VALIDATION_ERROR", "timeout_seconds must be an integer between 1 and 600.", field="timeout_seconds")

    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
    executions = _load("executions.json")
    usage = _load("usage_events.json")

    # Ambient auth resolution: pick an active key that can access this sandbox (or, if sandbox missing, any active key)
    sb = next((s for s in sandboxes if s.get("id") == sandbox_id), None)
    if sb:
        key = next((k for k in api_keys if k.get("id") == sb.get("api_key_id") and k.get("status") == "active"), None)
    else:
        key = next((k for k in api_keys if k.get("status") == "active"), None)
    if not key:
        # Must log rejected usage even without a valid active key; pick any key row for FK if possible
        any_key = next((k for k in api_keys if isinstance(k.get("id"), str)), None)
        if any_key:
            _record_usage(usage, any_key.get("id"), "executeJavaScript", "rejected", error_code="key_inactive", sandbox_id_val=sandbox_id)
            _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "No active API key is available to serve this request.", error_code="invalid_api_key")

    api_key_id = key["id"]

    # Rate limit (count all events in last 1s)
    if _rate_limited(usage, api_key_id, key.get("rate_limit_rps"), now):
        _record_usage(usage, api_key_id, "executeJavaScript", "rejected", error_code="rate_limited", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    # Quota exec/day
    exec_count = _count_today(
        usage,
        api_key_id,
        tools=("executePython", "executeJavaScript"),
        statuses=("accepted", "succeeded", "failed", "timeout", "cancelled"),
        now_utc=now,
    )
    quota_exec = key.get("quota_exec_per_day")
    if not isinstance(quota_exec, int) or quota_exec < 0:
        quota_exec = 0
    if exec_count >= quota_exec:
        _record_usage(usage, api_key_id, "executeJavaScript", "rejected", error_code="quota_exec_exceeded", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("QUOTA_EXCEEDED", "Daily execution quota exceeded.", error_code="quota_exec_exceeded")

    # Resolve/ensure sandbox
    changed_sb = False
    if sb:
        # Expire if idle ttl exceeded
        if _maybe_expire_sandbox(sb, now):
            changed_sb = True

        # For execute*, business rule does NOT forbid expired/error (only file ops do).
        # But if sandbox is expired or error, we create a new ready sandbox for this key.
        if sb.get("status") in ("expired", "error"):
            sb = None
    if not sb:
        # Find existing ready sandbox for key
        ready = None
        for s in sandboxes:
            if s.get("api_key_id") == api_key_id and s.get("status") == "ready":
                # expire check
                if _maybe_expire_sandbox(s, now):
                    changed_sb = True
                    continue
                ready = s
                break
        if not ready:
            # Create new sandbox provisioning -> ready
            sb_id = _gen_id("se2b_sbx")
            sb = {
                "id": sb_id,
                "api_key_id": api_key_id,
                "status": "provisioning",
                "region": None,
                "runtime_image": "smart-e2b/node:20-2025.06",
                "idle_ttl_seconds": 3600,
                "expires_at": None,
                "last_activity_at": _iso(now),
                "total_storage_bytes": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            sandboxes.append(sb)
            # Transition provisioning -> ready (legal)
            sb["status"] = "ready"
            sb["updated_at"] = _iso(now)
            changed_sb = True
        else:
            sb = ready

    # FK integrity: sandbox must belong to key
    if sb.get("api_key_id") != api_key_id:
        _record_usage(usage, api_key_id, "executeJavaScript", "rejected", error_code="fk_mismatch", sandbox_id_val=sb.get("id"))
        _save("usage_events.json", usage)
        return _err("CONFLICT", "Foreign key mismatch: sandbox does not belong to authenticated key.", error_code="fk_mismatch")

    # Create execution queued -> running -> terminal
    exe_id = _gen_id("se2b_exe")
    exe = {
        "id": exe_id,
        "sandbox_id": sb["id"],
        "api_key_id": api_key_id,
        "language": "javascript",
        "status": "queued",
        "code": code,
        "stdin": stdin,
        "stdout": "",
        "stderr": "",
        "exit_code": None,
        "started_at": None,
        "finished_at": None,
        "timeout_seconds": timeout_seconds,
        "cpu_millis": None,
        "memory_peak_bytes": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    executions.append(exe)

    # Usage accepted must be recorded for quota accounting
    _record_usage(usage, api_key_id, "executeJavaScript", "accepted", sandbox_id_val=sb["id"], execution_id_val=exe_id)

    # Update sandbox activity and set busy during run
    # Transitions: ready/stopped -> busy allowed; provisioning should not reach here; expired/error already handled
    if sb.get("status") in ("ready", "stopped"):
        sb["status"] = "busy"
        sb["updated_at"] = _iso(now)
        changed_sb = True
    sb["last_activity_at"] = _iso(now)
    sb["updated_at"] = _iso(now)
    changed_sb = True

    # Transition execution: queued -> running
    exe["status"] = "running"
    exe["started_at"] = _iso(now)
    exe["updated_at"] = _iso(now)

    # Simulate run (offline): enforce timeout for obvious infinite loops pattern; otherwise succeed.
    finished = _now()
    timed_out = False
    if "while(true)" in code.replace(" ", "") or "for(;;)" in code.replace(" ", ""):
        # if provided timeout_seconds is small/large doesn't matter; this code would run forever -> timeout
        timed_out = True

    if timed_out:
        exe["status"] = "timeout"
        exe["stdout"] = ""
        exe["stderr"] = f"Execution timed out after {timeout_seconds}s"
        exe["exit_code"] = None
    else:
        exe["status"] = "succeeded"
        exe["stdout"] = ""
        exe["stderr"] = ""
        exe["exit_code"] = 0

    exe["finished_at"] = _iso(finished)
    exe["updated_at"] = _iso(finished)

    # Sandbox back to ready if not stopped/expired
    if sb.get("status") == "busy":
        sb["status"] = "ready"
        sb["updated_at"] = _iso(finished)
        sb["last_activity_at"] = _iso(finished)
        changed_sb = True

    # Update key last_used_at on successful accepted call (even if execution timed out, it's a successful API call)
    key["last_used_at"] = _iso(finished)
    key["updated_at"] = _iso(finished)

    # Persist
    _save("executions.json", executions)
    if changed_sb:
        _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    # Final usage outcome (accepted -> succeeded/failed)
    # usage_events lifecycle allows accepted -> failed/succeeded only; map timeout/cancelled to failed for event status, keep error_code.
    out_status = "succeeded" if exe["status"] == "succeeded" else "failed"
    out_error = None if exe["status"] == "succeeded" else ("timeout" if exe["status"] == "timeout" else "execution_failed")
    _record_usage(usage, api_key_id, "executeJavaScript", out_status, error_code=out_error, sandbox_id_val=sb["id"], execution_id_val=exe_id, response_bytes=0)
    _save("usage_events.json", usage)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "execution": exe,
        "sandbox": {"id": sb["id"], "status": sb.get("status")},
        "latency_ms": latency_ms,
    }

