        last = _parse_dt(sb.get("last_activity_at")) if sb.get("last_activity_at") else None
        if not isinstance(ttl, int) or ttl < 30 or ttl > 86400:
            return False
        if not last:
            return False
        if sb.get("status") in ("ready", "busy", "stopped", "error"):
            if now_utc - last > datetime.timedelta(seconds=ttl):
                sb["status"] = "expired"
                sb["updated_at"] = _iso(now_utc)
                return True
        return False

    t0 = time.time()
    now = _now()

    # Validate inputs
    if not isinstance(sandbox_id, str) or not re.match(r"^se2b_sbx_[0-9A-Z]{18,}$", sandbox_id):
        return _err("VALIDATION_ERROR", "sandbox_id is invalid.", field="sandbox_id")
    if not isinstance(code, str) or code.strip() == "":
        return _err("VALIDATION_ERROR", "code is required and must be non-empty.", field="code")
