        return _err("VALIDATION_ERROR", "stdin must be a string.", field="stdin")
    if timeout_seconds is None:
        timeout_seconds = 60
    if not isinstance(timeout_seconds, int) or timeout_seconds < 1 or timeout_seconds > 600:
        return _err("VALIDATION_ERROR", "timeout_seconds must be an integer between 1 and 600.", field="timeout_seconds")

    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
