        ready = None
        for s in sandboxes:
            if s.get("api_key_id") == api_key_id and s.get("status") == "ready":
                if _maybe_expire_sandbox(s, now):
                    changed_sb = True
                    continue
                ready = s
                break
        if not ready:
            sb_id = _gen_id("se2b_sbx")
            sb = {
                "id": sb_id,
                "api_key_id": api_key_id,
                "status": "provisioning",
                "region": None,
                "runtime_image": "smart-e2b/python:3.12-2025.07",
                "idle_ttl_seconds": 3600,
                "expires_at": None,
                "last_activity_at": _iso(now),
                "total_storage_bytes": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            sandboxes.append(sb)
            sb["status"] = "ready"
            sb["updated_at"] = _iso(now)
            changed_sb = True
