    exe_id = _gen_id("se2b_exe")
    exe = {
        "id": exe_id,
        "sandbox_id": sb["id"],
        "api_key_id": api_key_id,
        "language": "python",
        "status": "queued",
        "code": code,
        "stdin": stdin,
        "stdout": "",
        "stderr": "",
        "exit_code": None,
        "started_at": None,
        "finished_at": None,
        "timeout_seconds": timeout_seconds,
        "cpu_millis": None,
        "memory_peak_bytes": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    executions.append(exe)
    _record_usage(usage, api_key_id, "executePython", "accepted", sandbox_id_val=sb["id"], execution_id_val=exe_id)

    # Sandbox busy, update activity
    if sb.get("status") in ("ready", "stopped"):
