        exe["stdout"] = ""
        exe["stderr"] = f"Execution timed out after {timeout_seconds}s"
        exe["exit_code"] = None
    else:
        exe["status"] = "succeeded"
        exe["stdout"] = ""
        exe["stderr"] = ""
        exe["exit_code"] = 0
    exe["finished_at"] = _iso(finished)
    exe["updated_at"] = _iso(finished)

