    _save("usage_events.json", usage)

    out_status = "succeeded" if exe["status"] == "succeeded" else "failed"
    out_error = None if exe["status"] == "succeeded" else ("timeout" if exe["status"] == "timeout" else "execution_failed")
    _record_usage(usage, api_key_id, "executePython", out_status, error_code=out_error, sandbox_id_val=sb["id"], execution_id_val=exe_id, response_bytes=0)
    _save("usage_events.json", usage)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "execution": exe,
        "sandbox": {"id": sb["id"], "status": sb.get("status")},
        "latency_ms": latency_ms,
    }

def uploadFile(sandbox_id, path, content_base64, content_type=None, **_extra):
    import json, os, datetime, re, base64, hashlib, secrets, time
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        suffix = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{suffix}"

    def _today_bounds(now_utc):
        start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _count_today(usage_rows, api_key_id, tools_set, statuses_set, now_utc):
        start, end = _today_bounds(now_utc)
        cnt = 0
        for r in usage_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            if r.get("tool") not in tools_set:
                continue
            if r.get("status") not in statuses_set:
                continue
            dt = _parse_dt(r.get("occurred_at"))
            if not dt:
                continue
            if start <= dt < end:
                cnt += 1
        return cnt

    def _rate_limited(usage_rows, api_key_id, rps, now_utc):
        try:
            rps = float(rps)
        except Exception:
            return False
        if rps <= 0:
            return False
        window_start = now_utc - datetime.timedelta(seconds=1)
        cnt = 0
        for r in usage_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        return cnt >= rps

    def _record_usage(usage_rows, api_key_id, tool, status, error_code=None, sandbox_id_val=None, execution_id_val=None, file_id=None, request_bytes=None, response_bytes=None):
        now = _now()
        ue = {
            "id": _gen_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id_val,
            "execution_id": execution_id_val,
            "file_id": file_id,
            "tool": tool,
            "status": status,
            "request_bytes": request_bytes,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        usage_rows.append(ue)
        return ue

    def _expire_if_idle(sb, now_utc):
        st = sb.get("status")
        if st in ("expired",):
            return False
        ttl = sb.get("idle_ttl_seconds")
        try:
            ttl = int(ttl)
        except Exception:
            return False
        if ttl < 30 or ttl > 86400:
            return False
        last = _parse_dt(sb.get("last_activity_at")) or _parse_dt(sb.get("created_at"))
        if not last:
            return False
        if now_utc - last > datetime.timedelta(seconds=ttl):
            # lifecycle allows ready/busy/stopped/provisioning -> expired? provisioning doesn't list expired; respect transitions
            transitions = {
                "provisioning": ["ready", "error", "stopped"],
                "ready": ["busy", "stopped", "expired", "error"],
                "busy": ["ready", "stopped", "expired", "error"],
                "stopped": ["ready", "expired"],
                "expired": [],
                "error": ["stopped"],
            }
            if "expired" in transitions.get(st, []):
                sb["status"] = "expired"
                sb["updated_at"] = _iso(now_utc)
                sb["expires_at"] = sb.get("expires_at") or _iso(now_utc)
                return True
        return False

    # Validate inputs
    if not isinstance(sandbox_id, str) or not re.match(r"^se2b_sbx_[0-9A-Z]{18,}$", sandbox_id):
        return _err("VALIDATION_ERROR", "sandbox_id is invalid.", field="sandbox_id")
    if not isinstance(path, str) or not path:
        return _err("VALIDATION_ERROR", "path is required.", field="path")
    if not path.startswith("/"):
        return _err("VALIDATION_ERROR", "path must be an absolute path starting with '/'.", field="path")
    if not isinstance(content_base64, str) or content_base64 == "":
        return _err("VALIDATION_ERROR", "content_base64 is required.", field="content_base64")
    if content_type is not None and not isinstance(content_type, str):
        return _err("VALIDATION_ERROR", "content_type must be a string.", field="content_type")

    now = _now()

    # Load store
    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
    files = _load("files.json")
    usage = _load("usage_events.json")

    # Resolve sandbox and api_key context (ambient auth)
    sb = next((s for s in sandboxes if s.get("id") == sandbox_id), None)
    if not sb:
        # try to at least log a rejected event with any active key (best-effort)
        ak_any = next((k for k in api_keys if k.get("status") == "active"), None)
        if ak_any:
            _record_usage(usage, ak_any.get("id"), "uploadFile", "rejected", error_code="sandbox_not_found", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
            _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Sandbox not found.", error_code="not_found")

    api_key_id = sb.get("api_key_id")
    ak = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not ak:
        # sandbox points to missing key: treat as unauthorized
        ak_any = next((k for k in api_keys if k.get("status") == "active"), None)
        if ak_any:
            _record_usage(usage, ak_any.get("id"), "uploadFile", "rejected", error_code="invalid_api_key", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
            _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "Invalid API key context.", error_code="invalid_api_key")
    if ak.get("status") != "active":
        _record_usage(usage, ak.get("id"), "uploadFile", "rejected", error_code="key_inactive", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_inactive")

    # Rate limit/quota checks (counting only file ops per rules)
    if _rate_limited(usage, ak["id"], ak.get("rate_limit_rps"), now):
        _record_usage(usage, ak["id"], "uploadFile", "rejected", error_code="rate_limited", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    file_ops_used = _count_today(usage, ak["id"], {"uploadFile", "listFiles", "readFile"}, {"accepted", "succeeded", "failed"}, now)
    try:
        quota_file = int(ak.get("quota_file_ops_per_day"))
    except Exception:
        quota_file = 0
    if quota_file >= 0 and file_ops_used >= quota_file:
        _record_usage(usage, ak["id"], "uploadFile", "rejected", error_code="quota_file_ops_exceeded", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
        _save("usage_events.json", usage)
        return _err("QUOTA_EXCEEDED", "Daily file operation quota exceeded.", error_code="quota_file_ops_exceeded")

    # Idle expiry check & sandbox availability rule
    sb_changed = _expire_if_idle(sb, now)
    if sb.get("status") in ("expired", "error"):
        _record_usage(usage, ak["id"], "uploadFile", "rejected", error_code="sandbox_unavailable", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
        if sb_changed:
            _save("sandboxes.json", sandboxes)
        _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Sandbox is no longer available.", error_code="sandbox_unavailable")

    # Accept request: record accepted first
    _record_usage(usage, ak["id"], "uploadFile", "accepted", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))

    # Decode base64 (relax: accept URL-safe and missing padding)
    decoded = None
    b64 = content_base64.strip()
    try:
        pad = (-len(b64)) % 4
        if pad:
            b64_padded = b64 + ("=" * pad)
        else:
            b64_padded = b64
        try:
            decoded = base64.b64decode(b64_padded, validate=True)
        except Exception:
            decoded = base64.urlsafe_b64decode(b64_padded)
    except Exception:
        _record_usage(usage, ak["id"], "uploadFile", "failed", error_code="invalid_base64", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "content_base64 must be valid base64.", field="content_base64")

    size_bytes = len(decoded)
    sha256 = hashlib.sha256(decoded).hexdigest()

    # Determine directory/name
    p = path
    if p != "/" and p.endswith("/"):
        p = p[:-1]
    name = p.split("/")[-1] if p != "/" else ""
    directory = "/".join(p.split("/")[:-1]) or "/"

    # Upsert logic: overwrite only existing ACTIVE. If existing is deleted, create new row.
    existing_active = None
    for f in files:
        if f.get("sandbox_id") == sandbox_id and f.get("path") == path and f.get("status") == "active":
            existing_active = f
            break

    # Storage: keep inline for simplicity (consistent with schema)
    storage_backend = "inline"
    content_inline_base64 = base64.b64encode(decoded).decode("ascii")

    # Enforce storage quota (sum active files across non-expired sandboxes after upload)
    # Compute per-key active sandboxes not expired
    sb_ids = set()
    for s in sandboxes:
        if s.get("api_key_id") == ak["id"] and s.get("status") != "expired":
            sb_ids.add(s.get("id"))
    total_before = 0
    for f in files:
        if f.get("status") != "active":
            continue
        if f.get("sandbox_id") not in sb_ids:
            continue
        try:
            total_before += int(f.get("size_bytes") or 0)
        except Exception:
            pass
    if existing_active:
        try:
            total_after = total_before - int(existing_active.get("size_bytes") or 0) + size_bytes
        except Exception:
            total_after = total_before + size_bytes
    else:
        total_after = total_before + size_bytes

    try:
        storage_quota = int(ak.get("quota_storage_bytes"))
    except Exception:
        storage_quota = 0
    if storage_quota >= 0 and total_after > storage_quota:
        _record_usage(usage, ak["id"], "uploadFile", "rejected", error_code="quota_storage_exceeded", sandbox_id_val=sandbox_id, request_bytes=len(content_base64))
        _save("usage_events.json", usage)
        return _err("QUOTA_EXCEEDED", "Storage quota exceeded for this API key.", error_code="quota_storage_exceeded")

    # Apply mutation
    now_iso = _iso(now)
    file_row = None
    if existing_active:
        existing_active["content_type"] = content_type
        existing_active["size_bytes"] = size_bytes
        existing_active["sha256"] = sha256
        existing_active["storage_backend"] = storage_backend
        existing_active["content_inline_base64"] = content_inline_base64
        existing_active["object_store_key"] = None
        existing_active["directory"] = directory
        existing_active["name"] = name
        existing_active["updated_at"] = now_iso
        file_row = existing_active
    else:
        file_row = {
            "id": _gen_id("se2b_fil"),
            "sandbox_id": sandbox_id,
            "created_by_execution_id": None,
            "path": path,
            "directory": directory,
            "name": name,
            "content_type": content_type,
            "size_bytes": size_bytes,
            "sha256": sha256,
            "storage_backend": storage_backend,
            "content_inline_base64": content_inline_base64,
            "object_store_key": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # ensure uniqueness among active already checked; if a deleted row exists that's fine (new version)
        files.append(file_row)

    # Update sandbox activity + cached storage size
    sb["last_activity_at"] = now_iso
    sb["updated_at"] = now_iso
    # recompute sandbox total active
    sb_total = 0
    for f in files:
        if f.get("sandbox_id") == sandbox_id and f.get("status") == "active":
            try:
                sb_total += int(f.get("size_bytes") or 0)
            except Exception:
                pass
    sb["total_storage_bytes"] = max(0, sb_total)

    # Mark success usage and include file_id
    _record_usage(usage, ak["id"], "uploadFile", "succeeded", sandbox_id_val=sandbox_id, file_id=file_row.get("id"), request_bytes=len(content_base64))

    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso

    _save("files.json", files)
    _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    # Response metadata (no content echo)
    return {
        "file": {
            "id": file_row.get("id"),
            "sandbox_id": file_row.get("sandbox_id"),
            "path": file_row.get("path"),
            "directory": file_row.get("directory"),
            "name": file_row.get("name"),
            "content_type": file_row.get("content_type"),
            "size_bytes": file_row.get("size_bytes"),
            "sha256": file_row.get("sha256"),
            "storage_backend": file_row.get("storage_backend"),
            "status": file_row.get("status"),
            "created_at": file_row.get("created_at"),
            "updated_at": file_row.get("updated_at"),
        },
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def listFiles(sandbox_id, directory, limit=None, cursor=None, status=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        suffix = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{suffix}"

    def _record_usage(usage, api_key_id, tool, status, error_code=None, sandbox_id_val=None, execution_id_val=None, file_id=None, request_bytes=None, response_bytes=None):
        now = _now()
        ue = {
            "id": _gen_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id_val,
            "execution_id": execution_id_val,
            "file_id": file_id,
            "tool": tool,
            "status": status,
            "request_bytes": request_bytes,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        usage.append(ue)
        return ue

    def _within_today(dt_str, now_utc):
        dt = _parse_dt(dt_str)
        if not dt:
            return False
        start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start <= dt < end

    def _count_today(usage, api_key_id, tools, statuses, now_utc):
        c = 0
        for e in usage:
            if e.get("api_key_id") != api_key_id:
                continue
            if e.get("tool") not in tools:
                continue
            if e.get("status") not in statuses:
                continue
            if _within_today(e.get("occurred_at"), now_utc):
                c += 1
        return c

    def _rate_limited(usage, api_key_id, rps, now_utc):
        try:
            rps = float(rps)
        except Exception:
            return False
        if rps <= 0:
            return False
        window_start = now_utc - datetime.timedelta(seconds=1)
        cnt = 0
        for e in usage:
            if e.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(e.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start and dt <= now_utc:
                cnt += 1
        return cnt >= rps

    def _maybe_expire_sandbox(sb, now_utc):
        if sb.get("status") == "expired":
            return False
        ttl = sb.get("idle_ttl_seconds")
        last = _parse_dt(sb.get("last_activity_at")) if sb.get("last_activity_at") else None
        if not isinstance(ttl, int) or ttl < 30 or ttl > 86400 or not last:
            return False
        if sb.get("status") in ("ready", "busy", "stopped", "error"):
            if now_utc - last > datetime.timedelta(seconds=ttl):
                sb["status"] = "expired"
                sb["updated_at"] = _iso(now_utc)
                return True
        return False

    now = _now()

    # Validate
    if not isinstance(sandbox_id, str) or not re.match(r"^se2b_sbx_[0-9A-Z]{18,}$", sandbox_id):
        return _err("VALIDATION_ERROR", "sandbox_id is invalid.", field="sandbox_id")
    if not isinstance(directory, str) or directory.strip() == "" or not directory.startswith("/"):
        return _err("VALIDATION_ERROR", "directory is required and must be an absolute path.", field="directory")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if status is not None and status not in ("active", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted.", field="status")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "path", "name", "size_bytes"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, path, name, size_bytes.", field="sort")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")

    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
    files = _load("files.json")
    usage = _load("usage_events.json")

    sb = next((s for s in sandboxes if s.get("id") == sandbox_id), None)
    if not sb:
        any_key = next((k for k in api_keys if isinstance(k.get("id"), str)), None)
        if any_key:
            _record_usage(usage, any_key["id"], "listFiles", "rejected", error_code="sandbox_unavailable", sandbox_id_val=sandbox_id)
            _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Sandbox not found.", error_code="sandbox_unavailable")

    key = next((k for k in api_keys if k.get("id") == sb.get("api_key_id")), None)
    if not key or key.get("status") != "active":
        if key:
            _record_usage(usage, key["id"], "listFiles", "rejected", error_code="key_inactive", sandbox_id_val=sandbox_id)
            _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is inactive or invalid.", error_code="key_inactive")

    api_key_id = key["id"]

    # Rate limit
    if _rate_limited(usage, api_key_id, key.get("rate_limit_rps"), now):
        _record_usage(usage, api_key_id, "listFiles", "rejected", error_code="rate_limited", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    # Expire sandbox if needed
    sb_changed = _maybe_expire_sandbox(sb, now)

    # File ops forbidden for expired/error
    if sb.get("status") in ("expired", "error"):
        _record_usage(usage, api_key_id, "listFiles", "rejected", error_code="sandbox_unavailable", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        if sb_changed:
            _save("sandboxes.json", sandboxes)
        return _err("CONFLICT", "Sandbox unavailable for file operations (expired or error).", error_code="sandbox_unavailable")

    # Quota file ops/day
    file_ops_count = _count_today(
        usage, api_key_id,
        tools=("uploadFile", "listFiles", "readFile"),
        statuses=("accepted", "succeeded", "failed"),
        now_utc=now
    )
    q_file = key.get("quota_file_ops_per_day")
    if not isinstance(q_file, int) or q_file < 0:
        q_file = 0
    if file_ops_count >= q_file:
        _record_usage(usage, api_key_id, "listFiles", "rejected", error_code="quota_file_ops_exceeded", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("QUOTA_EXCEEDED", "Daily file operations quota exceeded.", error_code="quota_file_ops_exceeded")

    # Business rule: listFiles must only return active and exact directory match (default '/')
    req_dir = directory.rstrip("/") if directory != "/" else "/"
    base = [f for f in files if f.get("sandbox_id") == sandbox_id and f.get("status") == "active" and (f.get("directory") == req_dir)]
    # ignore requested status filter per business rule (must not return deleted); but allow status=active only
    if status == "deleted":
        base = []

    def _key_fn(f):
        v = f.get(sort)
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt(v) if isinstance(v, str) else None
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort == "size_bytes":
            try:
                return int(v or 0)
            except Exception:
                return 0
        return "" if v is None else str(v)

    reverse = (order == "desc")
    base.sort(key=_key_fn, reverse=reverse)

    # Pagination cursor: treat as last seen file id
    start_index = 0
    if cursor:
        for i, f in enumerate(base):
            if f.get("id") == cursor:
                start_index = i + 1
                break

    page = base[start_index:start_index + limit]
    next_cursor = None
    has_more = start_index + limit < len(base)
    if has_more and page:
        next_cursor = page[-1].get("id")

    # Accepted usage and update sandbox activity
    _record_usage(usage, api_key_id, "listFiles", "accepted", sandbox_id_val=sandbox_id)
    sb["last_activity_at"] = _iso(now)
    sb["updated_at"] = _iso(now)
    sb_changed = True
    key["last_used_at"] = _iso(now)
    key["updated_at"] = _iso(now)

    _save("usage_events.json", usage)
    _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)

    # Succeeded usage for the operation
    _record_usage(usage, api_key_id, "listFiles", "succeeded", sandbox_id_val=sandbox_id, response_bytes=0)
    _save("usage_events.json", usage)

    return {
        "data": page,
        "pagination": {
            "total": len(base),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def readFile(sandbox_id, path, encoding=None, **_extra):
    import json, os, datetime, re, base64, time, secrets
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        suffix = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{suffix}"

    def _today_bounds(now_utc):
        start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _count_today(usage_rows, api_key_id, tools_set, statuses_set, now_utc):
        start, end = _today_bounds(now_utc)
        cnt = 0
        for r in usage_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            if r.get("tool") not in tools_set:
                continue
            if r.get("status") not in statuses_set:
                continue
            dt = _parse_dt(r.get("occurred_at"))
            if not dt:
                continue
            if start <= dt < end:
                cnt += 1
        return cnt

    def _rate_limited(usage_rows, api_key_id, rps, now_utc):
        try:
            rps = float(rps)
        except Exception:
            return False
        if rps <= 0:
            return False
        window_start = now_utc - datetime.timedelta(seconds=1)
        cnt = 0
        for r in usage_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        return cnt >= rps

    def _record_usage(usage_rows, api_key_id, tool, status, error_code=None, sandbox_id_val=None, execution_id_val=None, file_id=None, request_bytes=None, response_bytes=None):
        now = _now()
        ue = {
            "id": _gen_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id_val,
            "execution_id": execution_id_val,
            "file_id": file_id,
            "tool": tool,
            "status": status,
            "request_bytes": request_bytes,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        usage_rows.append(ue)
        return ue

    def _expire_if_idle(sb, now_utc):
        st = sb.get("status")
        if st in ("expired",):
            return False
        ttl = sb.get("idle_ttl_seconds")
        try:
            ttl = int(ttl)
        except Exception:
            return False
        if ttl < 30 or ttl > 86400:
            return False
        last = _parse_dt(sb.get("last_activity_at")) or _parse_dt(sb.get("created_at"))
        if not last:
            return False
        if now_utc - last > datetime.timedelta(seconds=ttl):
            transitions = {
                "provisioning": ["ready", "error", "stopped"],
                "ready": ["busy", "stopped", "expired", "error"],
                "busy": ["ready", "stopped", "expired", "error"],
                "stopped": ["ready", "expired"],
                "expired": [],
                "error": ["stopped"],
            }
            if "expired" in transitions.get(st, []):
                sb["status"] = "expired"
                sb["updated_at"] = _iso(now_utc)
                sb["expires_at"] = sb.get("expires_at") or _iso(now_utc)
                return True
        return False

    # Validate inputs
    if not isinstance(sandbox_id, str) or not re.match(r"^se2b_sbx_[0-9A-Z]{18,}$", sandbox_id):
        return _err("VALIDATION_ERROR", "sandbox_id is invalid.", field="sandbox_id")
    if not isinstance(path, str) or not path:
        return _err("VALIDATION_ERROR", "path is required.", field="path")
    if not path.startswith("/"):
        return _err("VALIDATION_ERROR", "path must be an absolute path starting with '/'.", field="path")
    if encoding is None:
        encoding = "base64"
    if not isinstance(encoding, str) or encoding not in ("base64", "utf-8"):
        return _err("VALIDATION_ERROR", "encoding must be one of: base64, utf-8.", field="encoding")

    now = _now()

    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
    files = _load("files.json")
    usage = _load("usage_events.json")

    sb = next((s for s in sandboxes if s.get("id") == sandbox_id), None)
    if not sb:
        ak_any = next((k for k in api_keys if k.get("status") == "active"), None)
        if ak_any:
            _record_usage(usage, ak_any.get("id"), "readFile", "rejected", error_code="sandbox_not_found", sandbox_id_val=sandbox_id)
            _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Sandbox not found.", error_code="not_found")

    api_key_id = sb.get("api_key_id")
    ak = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not ak:
        ak_any = next((k for k in api_keys if k.get("status") == "active"), None)
        if ak_any:
            _record_usage(usage, ak_any.get("id"), "readFile", "rejected", error_code="invalid_api_key", sandbox_id_val=sandbox_id)
            _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "Invalid API key context.", error_code="invalid_api_key")
    if ak.get("status") != "active":
        _record_usage(usage, ak.get("id"), "readFile", "rejected", error_code="key_inactive", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_inactive")

    if _rate_limited(usage, ak["id"], ak.get("rate_limit_rps"), now):
        _record_usage(usage, ak["id"], "readFile", "rejected", error_code="rate_limited", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    file_ops_used = _count_today(usage, ak["id"], {"uploadFile", "listFiles", "readFile"}, {"accepted", "succeeded", "failed"}, now)
    try:
        quota_file = int(ak.get("quota_file_ops_per_day"))
    except Exception:
        quota_file = 0
    if quota_file >= 0 and file_ops_used >= quota_file:
        _record_usage(usage, ak["id"], "readFile", "rejected", error_code="quota_file_ops_exceeded", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("QUOTA_EXCEEDED", "Daily file operation quota exceeded.", error_code="quota_file_ops_exceeded")

    sb_changed = _expire_if_idle(sb, now)
    if sb.get("status") in ("expired", "error"):
        _record_usage(usage, ak["id"], "readFile", "rejected", error_code="sandbox_unavailable", sandbox_id_val=sandbox_id)
        if sb_changed:
            _save("sandboxes.json", sandboxes)
        _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Sandbox is no longer available.", error_code="sandbox_unavailable")

    _record_usage(usage, ak["id"], "readFile", "accepted", sandbox_id_val=sandbox_id)

    frow = next((f for f in files if f.get("sandbox_id") == sandbox_id and f.get("path") == path and f.get("status") == "active"), None)
    if not frow:
        _record_usage(usage, ak["id"], "readFile", "failed", error_code="file_not_found", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        if sb_changed:
            _save("sandboxes.json", sandboxes)
        return _err("NOT_FOUND", "File not found.", error_code="file_not_found")

    data_bytes = None
    if frow.get("storage_backend") == "inline":
        b64 = frow.get("content_inline_base64")
        if b64 is None:
            _record_usage(usage, ak["id"], "readFile", "failed", error_code="content_missing", sandbox_id_val=sandbox_id, file_id=frow.get("id"))
            _save("usage_events.json", usage)
            return _err("NOT_FOUND", "File content is not available.", error_code="content_missing")
        try:
            pad = (-len(b64)) % 4
            if pad:
                b64p = b64 + ("=" * pad)
            else:
                b64p = b64
            try:
                data_bytes = base64.b64decode(b64p, validate=True)
            except Exception:
                data_bytes = base64.urlsafe_b64decode(b64p)
        except Exception:
            _record_usage(usage, ak["id"], "readFile", "failed", error_code="content_corrupt", sandbox_id_val=sandbox_id, file_id=frow.get("id"))
            _save("usage_events.json", usage)
            return _err("NOT_FOUND", "File content is not readable.", error_code="content_corrupt")
    elif frow.get("storage_backend") == "object_store":
        # Offline datastore: treat object_store_key as retrievable only if present in inline content; otherwise return not available
        # This matches business rule "must fetch by object_store_key" but we have no object store here.
        if not frow.get("object_store_key"):
            _record_usage(usage, ak["id"], "readFile", "failed", error_code="content_missing", sandbox_id_val=sandbox_id, file_id=frow.get("id"))
            _save("usage_events.json", usage)
            return _err("NOT_FOUND", "File content is not available.", error_code="content_missing")
        # Best-effort: if inline content exists despite object_store flag, use it.
        b64 = frow.get("content_inline_base64")
        if b64:
            try:
                pad = (-len(b64)) % 4
                b64p = b64 + ("=" * pad) if pad else b64
                data_bytes = base64.b64decode(b64p)
            except Exception:
                data_bytes = None
        if data_bytes is None:
            _record_usage(usage, ak["id"], "readFile", "failed", error_code="object_store_unavailable", sandbox_id_val=sandbox_id, file_id=frow.get("id"))
            _save("usage_events.json", usage)
            return _err("NOT_FOUND", "Object storage is not available in this offline datastore.", error_code="object_store_unavailable")
    else:
        _record_usage(usage, ak["id"], "readFile", "failed", error_code="storage_backend_invalid", sandbox_id_val=sandbox_id, file_id=frow.get("id"))
        _save("usage_events.json", usage)
        return _err("NOT_FOUND", "File storage backend is invalid.", error_code="storage_backend_invalid")

    # Update sandbox activity
    now_iso = _iso(now)
    sb["last_activity_at"] = now_iso
    sb["updated_at"] = now_iso
    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso

    # Build response content
    if encoding == "base64":
        content_out = base64.b64encode(data_bytes).decode("ascii")
    else:
        try:
            content_out = data_bytes.decode("utf-8")
        except Exception:
            _record_usage(usage, ak["id"], "readFile", "failed", error_code="decode_error", sandbox_id_val=sandbox_id, file_id=frow.get("id"))
            _save("usage_events.json", usage)
            return _err("VALIDATION_ERROR", "File content cannot be decoded as utf-8.", field="encoding")

    resp_bytes = len(content_out) if isinstance(content_out, str) else None
    _record_usage(usage, ak["id"], "readFile", "succeeded", sandbox_id_val=sandbox_id, file_id=frow.get("id"), response_bytes=resp_bytes)

    _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    return {
        "file": {
            "id": frow.get("id"),
            "sandbox_id": frow.get("sandbox_id"),
            "path": frow.get("path"),
            "content_type": frow.get("content_type"),
            "size_bytes": frow.get("size_bytes"),
            "sha256": frow.get("sha256"),
            "storage_backend": frow.get("storage_backend"),
            "status": frow.get("status"),
            "created_at": frow.get("created_at"),
            "updated_at": frow.get("updated_at"),
        },
        "encoding": encoding,
        "content": content_out,
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def getCaller(api_key, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _mk_id(prefix):
        token = base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
        return f"{prefix}_{token}"

    def _event(api_key_id, tool, status, error_code=None, response_bytes=None):
        usage = _load("usage_events.json")
        ev = {
            "id": _mk_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": None,
            "execution_id": None,
            "file_id": None,
            "tool": tool,
            "status": status,
            "request_bytes": None,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("usage_events.json", usage)
        return ev

    def _hash_prefix_from_presented(presented):
        # We cannot verify against key_hash (hash algorithm unknown), but we can match by key_prefix.
        # Use first 8 characters of presented key as prefix, consistent with schema description.
        if not isinstance(presented, str):
            return None
        return presented[:8]

    def _is_day(dt_iso):
        try:
            s = dt_iso
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt_utc = dt.astimezone(datetime.timezone.utc)
            start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            end = start + datetime.timedelta(days=1)
            return start <= dt_utc < end
        except Exception:
            return False

    if not isinstance(api_key, str) or not api_key:
        # log against any active key if possible
        keys = _load("api_keys.json")
        active = next((k for k in keys if k.get("status") == "active"), None)
        if active:
            _event(active["id"], "getCaller", "rejected", error_code="invalid_api_key")
        return _err("VALIDATION_ERROR", "api_key is required.", field="api_key")

    api_keys = _load("api_keys.json")
    usage = _load("usage_events.json")

    prefix = _hash_prefix_from_presented(api_key)
    key = None
    if prefix:
        # Authenticate by client-visible value or id; since plaintext isn't stored, match by prefix or by id.
        key = next((k for k in api_keys if k.get("key_prefix") == prefix), None)
    if not key:
        key = next((k for k in api_keys if k.get("id") == api_key), None)

    if not key:
        # no key to attach, so we cannot satisfy; spec asks UNAUTHORIZED
        return _err("UNAUTHORIZED", "Invalid API key.", error_code="invalid_api_key")

    if key.get("status") != "active":
        _event(key["id"], "getCaller", "rejected", error_code="key_inactive")
        return _err("UNAUTHORIZED", "API key inactive.", error_code="key_inactive")

    # rate limit check (per second)
    try:
        rps = float(key.get("rate_limit_rps"))
    except Exception:
        rps = None
    if not rps or rps <= 0:
        _event(key["id"], "getCaller", "rejected", error_code="rate_limit_misconfigured")
        return _err("RATE_LIMIT", "Rate limit unavailable.", error_code="rate_limit_misconfigured")

    window_start = now - datetime.timedelta(seconds=1)
    reqs = 0
    for ev in usage:
        if ev.get("api_key_id") != key["id"]:
            continue
        try:
            s = ev.get("occurred_at", "")
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            if dt >= window_start and dt <= now:
                reqs += 1
        except Exception:
            continue
    if reqs >= rps:
        _event(key["id"], "getCaller", "rejected", error_code="rate_limited")
        return _err("RATE_LIMIT", "Too many requests.", error_code="rate_limited")

    # accepted log (this endpoint is not in usage_events.tool enum; do not write invalid enum values)
    # Update last_used_at for a successful auth-based call anyway.
    key["last_used_at"] = now_iso
    key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # quota snapshot
    exec_used = 0
    file_used = 0
    for ev in usage:
        if ev.get("api_key_id") != key["id"] or not _is_day(ev.get("occurred_at", "")):
            continue
        if ev.get("tool") in ("executePython", "executeJavaScript") and ev.get("status") in ("accepted", "succeeded", "failed", "timeout", "cancelled"):
            exec_used += 1
        if ev.get("tool") in ("uploadFile", "listFiles", "readFile") and ev.get("status") in ("accepted", "succeeded", "failed"):
            file_used += 1

    resp = {
        "api_key_id": key.get("id"),
        "key_prefix": key.get("key_prefix"),
        "label": key.get("label"),
        "status": key.get("status"),
        "permissions": {
            "execute": True,
            "files": True,
            "sandboxes": True,
        },
        "quota": {
            "exec_per_day": key.get("quota_exec_per_day"),
            "exec_used_today": exec_used,
            "file_ops_per_day": key.get("quota_file_ops_per_day"),
            "file_ops_used_today": file_used,
            "storage_bytes_limit": key.get("quota_storage_bytes"),
        },
        "rate_limit": {
            "rps": key.get("rate_limit_rps"),
        },
        "last_used_at": key.get("last_used_at"),
        "created_at": key.get("created_at"),
        "updated_at": key.get("updated_at"),
        "latency_ms": int((time.time() - t0) * 1000),
    }
    return resp

def createSandbox(api_key, region=None, runtime_image=None, idle_ttl_seconds=None, reuse_if_ready=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    ALLOWED_REGIONS = {"us-east-1", "us-west-2", "eu-west-1", "eu-central-1", "ap-southeast-1"}

    def _mk_id(prefix):
        token = base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
        return f"{prefix}_{token}"

    def _event(api_key_id, status, sandbox_id=None, error_code=None, response_bytes=None):
        usage = _load("usage_events.json")
        ev = {
            "id": _mk_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id,
            "execution_id": None,
            "file_id": None,
            "tool": "listFiles",  # cannot log createSandbox (not in enum); use closest sandbox-touching file tool? would be wrong.
            "status": "rejected",
            "request_bytes": None,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # Do not write invalid tool enum; instead, avoid logging if tool not supported by schema.
        return None

    def _hash_prefix_from_presented(presented):
        if not isinstance(presented, str):
            return None
        return presented[:8]

    def _maybe_expire_sandboxes(sandboxes):
        changed = False
        for sb in sandboxes:
            if sb.get("status") == "expired":
                continue
            last = sb.get("last_activity_at")
            ttl = sb.get("idle_ttl_seconds")
            if isinstance(ttl, int) and ttl > 0 and last and sb.get("status") in ("ready", "busy", "stopped"):
                try:
                    s = last
                    if s.endswith("Z"):
                        s = s[:-1] + "+00:00"
                    dt = datetime.datetime.fromisoformat(s)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                    if now - dt > datetime.timedelta(seconds=ttl):
                        sb["status"] = "expired"
                        sb["updated_at"] = now_iso
                        changed = True
                except Exception:
                    pass
        return changed

    # Validate inputs
    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key is required.", field="api_key")
    if region is not None:
        if not isinstance(region, str) or region not in ALLOWED_REGIONS:
            return _err("VALIDATION_ERROR", "region must be one of the allowed values.", field="region")
    if runtime_image is not None and not isinstance(runtime_image, str):
        return _err("VALIDATION_ERROR", "runtime_image must be a string.", field="runtime_image")
    if idle_ttl_seconds is None:
        idle_ttl_seconds = 3600
    if not isinstance(idle_ttl_seconds, int) or idle_ttl_seconds < 60 or idle_ttl_seconds > 86400:
        return _err("VALIDATION_ERROR", "idle_ttl_seconds must be between 60 and 86400.", field="idle_ttl_seconds")
    if reuse_if_ready is None:
        reuse_if_ready = True
    if not isinstance(reuse_if_ready, bool):
        return _err("VALIDATION_ERROR", "reuse_if_ready must be a boolean.", field="reuse_if_ready")

    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
    usage = _load("usage_events.json")

    # Authenticate by key_prefix (preferred) or id.
    prefix = _hash_prefix_from_presented(api_key)
    key = None
    if prefix:
        key = next((k for k in api_keys if k.get("key_prefix") == prefix), None)
    if not key:
        key = next((k for k in api_keys if k.get("id") == api_key), None)
    if not key:
        # cannot log createSandbox into usage_events (tool enum doesn't include it)
        return _err("UNAUTHORIZED", "Invalid API key.", error_code="invalid_api_key")
    if key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key inactive.", error_code="key_inactive")

    # rate limit check (per second) using usage_events since that's all we have
    try:
        rps = float(key.get("rate_limit_rps"))
    except Exception:
        rps = None
    if not rps or rps <= 0:
        return _err("RATE_LIMIT", "Rate limit unavailable.", error_code="rate_limit_misconfigured")
    window_start = now - datetime.timedelta(seconds=1)
    reqs = 0
    for ev in usage:
        if ev.get("api_key_id") != key["id"]:
            continue
        try:
            s = ev.get("occurred_at", "")
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            if dt >= window_start and dt <= now:
                reqs += 1
        except Exception:
            continue
    if reqs >= rps:
        return _err("RATE_LIMIT", "Too many requests.", error_code="rate_limited")

    # background idle expiry
    if _maybe_expire_sandboxes(sandboxes):
        _save("sandboxes.json", sandboxes)

    # reuse
    if reuse_if_ready:
        cand = None
        for sb in sandboxes:
            if sb.get("api_key_id") == key["id"] and sb.get("status") == "ready":
                if region is None or sb.get("region") == region:
                    cand = sb
                    break
        if cand:
            cand["last_activity_at"] = now_iso
            cand["updated_at"] = now_iso
            key["last_used_at"] = now_iso
            key["updated_at"] = now_iso
            _save("sandboxes.json", sandboxes)
            _save("api_keys.json", api_keys)
            return {
                "sandbox": cand,
                "reused": True,
                "latency_ms": int((time.time() - t0) * 1000),
            }

    # create new sandbox: provisioning -> ready
    sb_id = _mk_id("se2b_sbx")
    chosen_region = region or "us-east-1"
    sb = {
        "id": sb_id,
        "api_key_id": key["id"],
        "status": "provisioning",
        "region": chosen_region,
        "runtime_image": runtime_image,
        "idle_ttl_seconds": idle_ttl_seconds,
        "expires_at": None,
        "last_activity_at": now_iso,
        "total_storage_bytes": 0,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    sandboxes.append(sb)
    # transition to ready (legal from provisioning)
    sb["status"] = "ready"
    sb["updated_at"] = now_iso

    key["last_used_at"] = now_iso
    key["updated_at"] = now_iso

    _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)

    return {
        "sandbox": sb,
        "reused": False,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def getSandbox(api_key, sandbox_id, **_extra):
    import json, os, datetime, re, secrets, time
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        suffix = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{suffix}"

    def _rate_limited(usage_rows, api_key_id, rps, now_utc):
        try:
            rps = float(rps)
        except Exception:
            return False
        if rps <= 0:
            return False
        window_start = now_utc - datetime.timedelta(seconds=1)
        cnt = 0
        for r in usage_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        return cnt >= rps

    def _record_usage(usage_rows, api_key_id, tool, status, error_code=None, sandbox_id_val=None, execution_id_val=None, file_id=None, request_bytes=None, response_bytes=None):
        now = _now()
        ue = {
            "id": _gen_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id_val,
            "execution_id": execution_id_val,
            "file_id": file_id,
            "tool": tool,
            "status": status,
            "request_bytes": request_bytes,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        usage_rows.append(ue)
        return ue

    def _expire_if_idle(sb, now_utc):
        st = sb.get("status")
        if st in ("expired",):
            return False
        ttl = sb.get("idle_ttl_seconds")
        try:
            ttl = int(ttl)
        except Exception:
            return False
        if ttl < 30 or ttl > 86400:
            return False
        last = _parse_dt(sb.get("last_activity_at")) or _parse_dt(sb.get("created_at"))
        if not last:
            return False
        if now_utc - last > datetime.timedelta(seconds=ttl):
            transitions = {
                "provisioning": ["ready", "error", "stopped"],
                "ready": ["busy", "stopped", "expired", "error"],
                "busy": ["ready", "stopped", "expired", "error"],
                "stopped": ["ready", "expired"],
                "expired": [],
                "error": ["stopped"],
            }
            if "expired" in transitions.get(st, []):
                sb["status"] = "expired"
                sb["updated_at"] = _iso(now_utc)
                sb["expires_at"] = sb.get("expires_at") or _iso(now_utc)
                return True
        return False

    # Validate
    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key is required.", field="api_key")
    if not isinstance(sandbox_id, str) or not re.match(r"^se2b_sbx_[0-9A-Z]{18,}$", sandbox_id):
        return _err("VALIDATION_ERROR", "sandbox_id is invalid.", field="sandbox_id")

    now = _now()
    api_keys = _load("api_keys.json")
    sandboxes = _load("sandboxes.json")
    usage = _load("usage_events.json")

    # Authenticate by id or by key_prefix match (plaintext is not stored, so we can't verify full key)
    ak = next((k for k in api_keys if k.get("id") == api_key), None)
    if not ak:
        # allow passing key_prefix as credential
        ak = next((k for k in api_keys if k.get("key_prefix") == api_key), None)
    if not ak:
        # rejected usage must exist; choose any active key for logging if possible
        ak_any = next((k for k in api_keys if k.get("status") == "active"), None)
        if ak_any:
            _record_usage(usage, ak_any.get("id"), "getSandbox", "rejected", error_code="invalid_api_key", sandbox_id_val=sandbox_id)
            _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "Invalid API key.", error_code="invalid_api_key")
    if ak.get("status") != "active":
        _record_usage(usage, ak.get("id"), "getSandbox", "rejected", error_code="key_inactive", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_inactive")

    if _rate_limited(usage, ak["id"], ak.get("rate_limit_rps"), now):
        _record_usage(usage, ak["id"], "getSandbox", "rejected", error_code="rate_limited", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    sb = next((s for s in sandboxes if s.get("id") == sandbox_id and s.get("api_key_id") == ak.get("id")), None)
    if not sb:
        _record_usage(usage, ak.get("id"), "getSandbox", "rejected", error_code="not_found", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Sandbox not found.", error_code="not_found")

    sb_changed = _expire_if_idle(sb, now)

    _record_usage(usage, ak.get("id"), "getSandbox", "succeeded", sandbox_id_val=sandbox_id)

    now_iso = _iso(now)
    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso

    if sb_changed:
        _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    return {
        "sandbox": dict(sb),
        "latency_ms": int((time.time() - _t0) * 1000),
    }

