        return _err("NOT_FOUND", "Sandbox not found.", error_code="not_found")

    transitions = {
        "provisioning": ["ready", "error", "stopped"],
        "ready": ["busy", "stopped", "expired", "error"],
        "busy": ["ready", "stopped", "expired", "error"],
        "stopped": ["ready", "expired"],
        "expired": [],
        "error": ["stopped"],
    }

    cur = sb.get("status")
    if cur == "ready":
        _record_usage(usage, ak.get("id"), "resumeSandbox", "succeeded", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return {"sandbox": dict(sb), "latency_ms": int((time.time() - _t0) * 1000)}

    if cur == "expired":
        _record_usage(usage, ak.get("id"), "resumeSandbox", "rejected", error_code="sandbox_expired", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("CONFLICT", "Sandbox is expired and cannot be resumed.", error_code="sandbox_expired")

    if "ready" not in transitions.get(cur, []):
        _record_usage(usage, ak.get("id"), "resumeSandbox", "rejected", error_code="invalid_transition", sandbox_id_val=sandbox_id)
        _save("usage_events.json", usage)
        return _err("CONFLICT", f"Cannot transition sandbox from '{cur}' to 'ready'.", error_code="invalid_transition")

    sb["status"] = "ready"
    now_iso = _iso(now)
    sb["updated_at"] = now_iso
    sb["last_activity_at"] = now_iso
    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso

    _record_usage(usage, ak.get("id"), "resumeSandbox", "succeeded", sandbox_id_val=sandbox_id)

    _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    return {"sandbox": dict(sb), "latency_ms": int((time.time() - _t0) * 1000)}

def cancelExecution(api_key, execution_id, **_extra):
    import json, os, datetime, re, secrets, time
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0272000" if __import__("os").path.isdir("./environment_mix/0272000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        suffix = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{suffix}"

    def _rate_limited(usage_rows, api_key_id, rps, now_utc):
        try:
            rps = float(rps)
        except Exception:
            return False
        if rps <= 0:
            return False
        window_start = now_utc - datetime.timedelta(seconds=1)
        cnt = 0
        for r in usage_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        return cnt >= rps

    def _record_usage(usage_rows, api_key_id, tool, status, error_code=None, sandbox_id_val=None, execution_id_val=None, file_id=None, request_bytes=None, response_bytes=None):
        now = _now()
        ue = {
            "id": _gen_id("se2b_use"),
            "api_key_id": api_key_id,
            "sandbox_id": sandbox_id_val,
            "execution_id": execution_id_val,
            "file_id": file_id,
            "tool": tool,
            "status": status,
            "request_bytes": request_bytes,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        usage_rows.append(ue)
        return ue

    # Validate
    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key is required.", field="api_key")
    if not isinstance(execution_id, str) or not re.match(r"^se2b_exe_[0-9A-Z]{18,}$", execution_id):
        return _err("VALIDATION_ERROR", "execution_id is invalid.", field="execution_id")

    now = _now()
    api_keys = _load("api_keys.json")
    executions = _load("executions.json")
    sandboxes = _load("sandboxes.json")
    usage = _load("usage_events.json")

    ak = next((k for k in api_keys if k.get("id") == api_key), None) or next((k for k in api_keys if k.get("key_prefix") == api_key), None)
    if not ak:
        ak_any = next((k for k in api_keys if k.get("status") == "active"), None)
        if ak_any:
            _record_usage(usage, ak_any.get("id"), "cancelExecution", "rejected", error_code="invalid_api_key", execution_id_val=execution_id)
            _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "Invalid API key.", error_code="invalid_api_key")
    if ak.get("status") != "active":
        _record_usage(usage, ak.get("id"), "cancelExecution", "rejected", error_code="key_inactive", execution_id_val=execution_id)
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_inactive")

    if _rate_limited(usage, ak["id"], ak.get("rate_limit_rps"), now):
        _record_usage(usage, ak["id"], "cancelExecution", "rejected", error_code="rate_limited", execution_id_val=execution_id)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    exe = next((e for e in executions if e.get("id") == execution_id and e.get("api_key_id") == ak.get("id")), None)
    if not exe:
        _record_usage(usage, ak.get("id"), "cancelExecution", "rejected", error_code="not_found", execution_id_val=execution_id)
        _save("usage_events.json", usage)
        return _err("NOT_FOUND", "Execution not found.", error_code="not_found")

    transitions = {
        "queued": ["running", "cancelled"],
        "running": ["succeeded", "failed", "timeout", "cancelled"],
        "succeeded": [],
        "failed": [],
        "timeout": [],
        "cancelled": [],
    }
    cur = exe.get("status")
    if cur in ("succeeded", "failed", "timeout", "cancelled"):
        _record_usage(usage, ak.get("id"), "cancelExecution", "rejected", error_code="already_terminal", execution_id_val=execution_id, sandbox_id_val=exe.get("sandbox_id"))
        _save("usage_events.json", usage)
        return _err("CONFLICT", f"Execution is already terminal ({cur}) and cannot be cancelled.", error_code="already_terminal")

    if "cancelled" not in transitions.get(cur, []):
        _record_usage(usage, ak.get("id"), "cancelExecution", "rejected", error_code="invalid_transition", execution_id_val=execution_id, sandbox_id_val=exe.get("sandbox_id"))
        _save("usage_events.json", usage)
        return _err("CONFLICT", f"Cannot transition execution from '{cur}' to 'cancelled'.", error_code="invalid_transition")

    # Apply transition
    now_iso = _iso(now)
    exe["status"] = "cancelled"
    exe["updated_at"] = now_iso
    exe["finished_at"] = exe.get("finished_at") or now_iso
    exe["stderr"] = exe.get("stderr") if (exe.get("stderr") is not None and exe.get("stderr") != "") else "Cancelled by caller"
    if exe.get("exit_code") is None:
        exe["exit_code"] = -1

    # Update sandbox back to ready if it was running/busy and belongs to same key
    sb_id = exe.get("sandbox_id")
    sb = next((s for s in sandboxes if s.get("id") == sb_id), None)
    if sb and sb.get("api_key_id") == ak.get("id"):
        sb["last_activity_at"] = now_iso
        sb["updated_at"] = now_iso
        if sb.get("status") == "busy":
            sb["status"] = "ready"

    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso

    _record_usage(usage, ak.get("id"), "cancelExecution", "succeeded", execution_id_val=execution_id, sandbox_id_val=sb_id)

    _save("executions.json", executions)
    _save("sandboxes.json", sandboxes)
    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    return {"execution": dict(exe), "latency_ms": int((time.time() - _t0) * 1000)}
